    when(projectDao.getProjectsInGroup(anyInt())).thenReturn(projects);
    when(buildDefinitionDao.getBuildDefinition(1)).thenReturn(buildDef);
    when(buildDefinitionDao.getDefaultBuildDefinition(2)).thenReturn(buildDef);
